    13	public class Main {
    14	    public static void main(String[] args) {
    15	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
    16	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
    17	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
    18	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    19	
    20	        DatabaseManager.initialize(dbUrl, dbUser, dbPassword);
    21	
    22	        RoomRepository roomRepository = new RoomRepository();
    23	        ReservationRepository reservationRepository = new ReservationRepository();
    24	        MessageRepository messageRepository = new MessageRepository();
    25	
    26	        PricingService pricingService = new PricingService();
    27	        ReservationService reservationService = new ReservationService(
    28	            reservationRepository, roomRepository, messageRepository, pricingService
    29	        );
    30	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
    31	
    32	        RoomController roomController = new RoomController(roomRepository);
    33	        ReservationController reservationController = new ReservationController(reservationService);
    34	        MessageController messageController = new MessageController(messageRepository);
    35	        ReportController reportController = new ReportController(reportService);
    36	
    37	        ObjectMapper objectMapper = new ObjectMapper();
    38	        objectMapper.registerModule(new JavaTimeModule());
    39	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    40	        objectMapper.setPropertyNamingStrategy(PropertyNamingStrategies.LOWER_CAMEL_CASE);
    41	
    42	        Javalin app = Javalin.create(config -> {
    43	            config.jsonMapper(new JavalinJackson(objectMapper, true));
    44	        });
    45	
    46	        app.get("/rooms", roomController::getRooms);
    47	        app.post("/reservations", reservationController::createReservation);
    48	        app.get("/reservations/{id}", reservationController::getReservation);
    49	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
    50	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
    51	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
    52	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
    53	        app.get("/reservations/{id}/document", reservationController::getDocument);
    54	        app.get("/messages", messageController::getMessages);
    55	        app.get("/reports/occupancy", reportController::getOccupancyReport);
    56	        app.get("/reports/revenue", reportController::getRevenueReport);
    57	
    58	        app.start(port);
    59	
    60	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
    61	            app.stop();
    62	            DatabaseManager.shutdown();
    63	        }));
