    18	    public ReservationController(ReservationService reservationService) {
    19	        this.reservationService = reservationService;
    20	    }
    21	
    22	    public void createReservation(Context ctx) {
    23	        try {
    24	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
    25	
    26	            if (!json.has("roomNumber") || !json.has("guestName") || !json.has("guestEmail") ||
    27	                !json.has("guestCpf") || !json.has("checkIn") || !json.has("checkOut") ||
    28	                !json.has("guests") || !json.has("ratePlan")) {
    29	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
    30	                return;
    31	            }
    32	
    33	            String roomNumber = json.get("roomNumber").asText();
    34	            String guestName = json.get("guestName").asText();
    35	            String guestEmail = json.get("guestEmail").asText();
    36	            String guestCpf = json.get("guestCpf").asText();
    37	            LocalDate checkIn = LocalDate.parse(json.get("checkIn").asText());
    38	            LocalDate checkOut = LocalDate.parse(json.get("checkOut").asText());
    39	            int guests = json.get("guests").asInt();
    40	            RatePlan ratePlan = RatePlan.valueOf(json.get("ratePlan").asText());
    41	            String companyCode = json.has("companyCode") ? json.get("companyCode").asText() : null;
    42	
    43	            if (!checkOut.isAfter(checkIn)) {
    44	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
    45	                return;
    46	            }
    47	
    48	            Reservation reservation = reservationService.createReservation(
    49	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode
    50	            );
    51	
    52	            ctx.status(201).json(reservation);
    53	
    54	        } catch (DateTimeParseException e) {
    55	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    56	        } catch (IllegalArgumentException e) {
    57	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    58	        } catch (ReservationService.RoomNotFoundException e) {
    59	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
    60	        } catch (ReservationService.RoomUnavailableException e) {
    61	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
    62	        } catch (ReservationService.CapacityExceededException e) {
    63	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
    64	        } catch (ReservationService.InvalidRequestException e) {
    65	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    66	        } catch (Exception e) {
    67	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request body"));
    68	        }
    69	    }
    70	
    71	    public void getReservation(Context ctx) {
    72	        try {
    73	            Long id = Long.parseLong(ctx.pathParam("id"));
    74	            Reservation reservation = reservationService.getReservation(id);
    75	            ctx.json(reservation);
    76	        } catch (ReservationService.ReservationNotFoundException e) {
    77	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    78	        } catch (NumberFormatException e) {
    79	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
    80	        }
    81	    }
    82	
