     7	import java.util.HashMap;
     8	import java.util.List;
     9	import java.util.Map;
    10	import java.util.stream.Collectors;
    11	
    12	public class RoomController {
    13	
    14	    private final RoomRepository roomRepository;
    15	
    16	    public RoomController(RoomRepository roomRepository) {
    17	        this.roomRepository = roomRepository;
    18	    }
    19	
    20	    public void getRooms(Context ctx) {
    21	        List<Room> rooms = roomRepository.findAll();
    22	
    23	        List<Map<String, Object>> response = rooms.stream()
    24	            .map(room -> {
    25	                Map<String, Object> map = new HashMap<>();
    26	                map.put("number", room.getNumber());
    27	                map.put("type", room.getType().name());
    28	                map.put("capacity", room.getCapacity());
    29	                map.put("nightlyRate", room.getNightlyRate());
    30	                return map;
    31	            })
    32	            .collect(Collectors.toList());
    33	
    34	        ctx.json(response);
    35	    }
    36	}

