    64	                    reservation.getRoomNumber(),
    65	                    reservation.getCheckIn().format(DATE_FORMATTER),
    66	                    reservation.getCheckOut().format(DATE_FORMATTER),
    67	                    reservation.getStatus().name(),
    68	                    revenue
    69	                ));
    70	
    71	                totalRevenue = totalRevenue.add(revenue);
    72	            }
