     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.model.RatePlan;
     4	import com.pousadamarealta.model.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.DayOfWeek;
     9	import java.time.LocalDate;
    10	import java.time.Month;
    11	import java.util.Map;
    12	
    13	public class PricingService {
    14	
    15	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    16	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    17	    private static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    18	    private static final BigDecimal WEEKEND_REFUND_RATE = new BigDecimal("0.50");
    19	
    20	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
    21	        "TECNOSUL", new BigDecimal("0.12"),
    22	        "AGROVALE", new BigDecimal("0.18"),
    23	        "FARMAVIDA", new BigDecimal("0.25")
    24	    );
    25	
    26	    public static class PricingResult {
    27	        public final int nights;
    28	        public final BigDecimal subtotal;
    29	        public final BigDecimal discount;
    30	        public final BigDecimal total;
    31	
    32	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    33	            this.nights = nights;
    34	            this.subtotal = subtotal;
    35	            this.discount = discount;
    36	            this.total = total;
    37	        }
    38	    }
    39	
    40	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut,
    41	                                       RatePlan ratePlan, String companyCode) {
    42	        int nights = (int) checkIn.until(checkOut).getDays();
    43	
    44	        return switch (ratePlan) {
    45	            case STANDARD -> calculateStandardPrice(room, checkIn, checkOut, nights);
    46	            case NON_REFUNDABLE -> calculateNonRefundablePrice(room, checkIn, checkOut, nights);
    47	            case CORPORATE -> calculateCorporatePrice(room, checkIn, checkOut, nights, companyCode);
    48	            case WEEKEND_PACKAGE -> calculateWeekendPackagePrice(room);
    49	            case LONG_STAY -> calculateLongStayPrice(room, checkIn, checkOut, nights);
    50	        };
    51	    }
    52	
    53	    private PricingResult calculateStandardPrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    54	        BigDecimal subtotal = calculateNightlyTotal(room, checkIn, checkOut);
    55	        return new PricingResult(nights, subtotal, BigDecimal.ZERO, subtotal);
    56	    }
    57	
    58	    private PricingResult calculateNonRefundablePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    59	        BigDecimal subtotal = calculateNightlyTotal(room, checkIn, checkOut);
    60	        BigDecimal discount = round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    61	        BigDecimal total = subtotal.subtract(discount);
    62	        return new PricingResult(nights, subtotal, discount, total);
    63	    }
    64	
    65	    private PricingResult calculateCorporatePrice(Room room, LocalDate checkIn, LocalDate checkOut,
    66	                                                  int nights, String companyCode) {
    67	        BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
    68	        if (discountRate == null) {
    69	            throw new IllegalArgumentException("Invalid company code");
    70	        }
    71	
    72	        BigDecimal subtotal = calculateNightlyTotal(room, checkIn, checkOut);
    73	        BigDecimal discount = round(subtotal.multiply(discountRate));
    74	        BigDecimal total = subtotal.subtract(discount);
    75	        return new PricingResult(nights, subtotal, discount, total);
    76	    }
    77	
    78	    private PricingResult calculateWeekendPackagePrice(Room room) {
    79	        BigDecimal packagePrice = room.getType().getWeekendPackagePrice();
    80	        return new PricingResult(2, packagePrice, BigDecimal.ZERO, packagePrice);
    81	    }
    82	
    83	    private PricingResult calculateLongStayPrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    84	        BigDecimal subtotal = calculateNightlyTotal(room, checkIn, checkOut);
    85	        BigDecimal discount = round(subtotal.multiply(LONG_STAY_DISCOUNT));
    86	        BigDecimal total = subtotal.subtract(discount);
    87	        return new PricingResult(nights, subtotal, discount, total);
    88	    }
    89	
    90	    private BigDecimal calculateNightlyTotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    91	        BigDecimal total = BigDecimal.ZERO;
    92	        LocalDate currentDate = checkIn;
    93	
    94	        while (currentDate.isBefore(checkOut)) {
    95	            BigDecimal nightPrice = calculateNightPrice(room, currentDate);
    96	            total = total.add(nightPrice);
    97	            currentDate = currentDate.plusDays(1);
    98	        }
    99	
   100	        return round(total);
   101	    }
   102	
   103	    private BigDecimal calculateNightPrice(Room room, LocalDate date) {
   104	        BigDecimal baseRate = room.getNightlyRate();
   105	
   106	        if (isHighSeason(date)) {
   107	            baseRate = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
   108	        }
   109	
   110	        return round(baseRate);
   111	    }
   112	
   113	    private boolean isHighSeason(LocalDate date) {
   114	        Month month = date.getMonth();
   115	        int day = date.getDayOfMonth();
   116	
   117	        if (month == Month.DECEMBER && day >= 15) {
   118	            return true;
   119	        }
   120	
   121	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
   122	            return true;
   123	        }
   124	
   125	        if (month == Month.JULY) {
   126	            return true;
   127	        }
   128	
   129	        return false;
   130	    }
   131	
   132	    public BigDecimal calculateRefund(RatePlan ratePlan, BigDecimal amountPaid) {
   133	        return switch (ratePlan) {
   134	            case STANDARD, CORPORATE, LONG_STAY -> amountPaid;
   135	            case NON_REFUNDABLE -> BigDecimal.ZERO;
   136	            case WEEKEND_PACKAGE -> round(amountPaid.multiply(WEEKEND_REFUND_RATE));
   137	        };
   138	    }
   139	
   140	    public void validateRatePlan(RatePlan ratePlan, LocalDate checkIn, LocalDate checkOut,
   141	                                String companyCode) {
   142	        int nights = (int) checkIn.until(checkOut).getDays();
   143	
   144	        switch (ratePlan) {
   145	            case CORPORATE:
   146	                if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
   147	                    throw new IllegalArgumentException("Invalid company code for corporate rate plan");
   148	                }
   149	                break;
   150	            case WEEKEND_PACKAGE:
   151	                if (nights != 2 || checkIn.getDayOfWeek() != DayOfWeek.FRIDAY ||
   152	                    checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
   153	                    throw new IllegalArgumentException("Weekend package requires Friday check-in and Sunday check-out");
   154	                }
   155	                break;
   156	            case LONG_STAY:
   157	                if (nights < 7) {
   158	                    throw new IllegalArgumentException("Long stay requires minimum 7 nights");
   159	                }
   160	                break;
   161	        }
   162	    }
   163	
   164	    private BigDecimal round(BigDecimal value) {
   165	        return value.setScale(2, RoundingMode.HALF_EVEN);
   166	    }
   167	}
