   197	            reservation.getGuestEmail(),
   198	            "Reserva confirmada - Pousada Maré Alta",
   199	            emailBody
   200	        );
   201	
   202	        messageRepository.save(message);
   203	    }
   204	
   205	    private String formatReceiptText(ReceiptResponse receipt) {
   206	        StringBuilder sb = new StringBuilder();
   207	        sb.append(String.format("Comprovante de reserva nº %d%n", receipt.getReservationId()));
   208	        sb.append(String.format("Hóspede: %s (CPF %s)%n", receipt.getGuestName(), receipt.getGuestCpf()));
   209	        sb.append(String.format("Quarto: %s (%s)%n", receipt.getRoomNumber(), receipt.getRoomType()));
   210	
   211	        String nightsText = receipt.getNights() == 1 ? "1 diária" : receipt.getNights() + " diárias";
   212	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
   213	            receipt.getCheckIn(), receipt.getCheckOut(), nightsText));
   214	
   215	        sb.append(String.format("Diárias: %s%n", formatMoney(receipt.getSubtotal())));
   216	
   217	        if (receipt.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   218	            sb.append(String.format("Desconto: %s%n", formatMoney(receipt.getDiscount())));
   219	        }
   220	
   221	        sb.append(String.format("Total: %s", formatMoney(receipt.getTotal())));
   222	
   223	        return sb.toString();
   224	    }
   225	
   226	    private String formatMoney(BigDecimal value) {
   227	        return String.format("R$ %,.2f", value).replace(',', '#').replace('.', ',').replace('#', '.');
   228	    }
   229	
   230	    private String formatCpf(String cpf) {
   231	        if (cpf.length() == 11) {
   232	            return String.format("%s.%s.%s-%s",
   233	                cpf.substring(0, 3),
   234	                cpf.substring(3, 6),
   235	                cpf.substring(6, 9),
   236	                cpf.substring(9, 11)
   237	            );
   238	        }
   239	        return cpf;
   240	    }
