    35	            dataSource.close();
    36	        }
    37	    }
    38	
    39	    private static void createTables() {
    40	        try (Connection conn = getConnection();
    41	             Statement stmt = conn.createStatement()) {
    42	
    43	            stmt.execute("""
    44	                CREATE TABLE IF NOT EXISTS rooms (
    45	                    number VARCHAR(10) PRIMARY KEY,
    46	                    type VARCHAR(20) NOT NULL
    47	                )
    48	            """);
    49	
    50	            stmt.execute("""
